class Scale(keras.layers.Layer):
    def __init__(self, k=2.0, **kw):
        super().__init__(**kw)
        self.k = k
    def build(self, input_shape):
        self.w = self.add_weight(shape=(input_shape[-1],), initializer='ones', trainable=True, name='w')
        self.c = self.add_weight(shape=(), initializer='zeros', trainable=False, name='c')
    def call(self, x):
        return x * self.w * self.k + self.c
    def get_config(self):
        return {**super().get_config(), 'k': self.k}
